<template>
  <section class="content-page">
    <div class="catalog-heading"><div><p class="eyebrow">商城首页运营</p><h1>轮播图与公告</h1></div></div>
    <div class="content-tabs" role="tablist"><button :aria-pressed="tab==='carousel'" @click="switchTab('carousel')">轮播图</button><button :aria-pressed="tab==='announcement'" @click="switchTab('announcement')">公告</button></div>
    <p v-if="error" class="form-error" role="alert">{{ error }} <button class="text-action" @click="load">重试</button></p>
    <p v-if="loading" class="page-status">正在读取内容…</p>
    <template v-else-if="tab==='carousel'">
      <div class="content-toolbar"><span>{{ carousels.length }} 项</span><button class="primary-button" @click="newCarousel">新增轮播图</button></div>
      <div class="content-list"><article v-for="item in carousels" :key="item.id" class="content-row"><img :src="carouselImage(item.storageKey)" alt="轮播图预览"><div class="content-row-main"><strong>{{ item.title || '未命名轮播图' }}</strong><small>{{ item.startAt }}{{ item.endAt ? ` 至 ${item.endAt}` : ' 起持续展示' }}</small><small>排序 {{ item.sortOrder }} · {{ item.enabled ? '启用' : '停用' }}</small></div><button class="text-action" @click="editCarousel(item)">编辑</button></article><p v-if="!carousels.length" class="empty-state">暂无轮播图</p></div>
      <form v-if="carouselDraft" class="content-editor" @submit.prevent="saveCarousel"><div class="editor-heading"><h2>{{ carouselDraft.id ? '编辑轮播图' : '新增轮播图' }}</h2><button class="icon-close" type="button" aria-label="关闭" @click="carouselDraft=null">×</button></div><div class="content-fields"><label>图片<input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadImage"><img v-if="carouselDraft.storageKey" class="image-preview" :src="carouselImage(carouselDraft.storageKey)" alt="已选图片"></label><label>标题<input v-model.trim="carouselDraft.title" maxlength="100"></label><label>跳转目标<input v-model.trim="carouselDraft.targetUrl" maxlength="500" placeholder="站内路径或 https:// 地址"></label><label>排序<input v-model.number="carouselDraft.sortOrder" type="number" min="0"></label><label>开始时间<input v-model="carouselDraft.startAt" type="datetime-local" required></label><label>结束时间<input v-model="carouselDraft.endAt" type="datetime-local"></label><label class="inline-option"><input v-model="carouselDraft.enabled" type="checkbox">启用</label></div><p v-if="saveError" class="form-error">{{ saveError }}</p><button class="primary-button" :disabled="saving">{{ saving?'保存中…':'保存轮播图' }}</button></form>
    </template>
    <template v-else>
      <div class="content-toolbar"><span>{{ announcements.length }} 项</span><button class="primary-button" @click="newAnnouncement">新增公告</button></div>
      <div class="content-list"><article v-for="item in announcements" :key="item.id" class="announcement-row"><div><strong>{{ item.pinned?'置顶 · ':'' }}{{ item.title }}</strong><p>{{ item.summary || item.body }}</p><small>{{ item.startAt }}{{ item.endAt ? ` 至 ${item.endAt}` : ' 起持续展示' }} · {{ item.enabled?'启用':'停用' }} · 排序 {{ item.sortOrder }}</small></div><button class="text-action" @click="editAnnouncement(item)">编辑</button></article><p v-if="!announcements.length" class="empty-state">暂无公告</p></div>
      <form v-if="announcementDraft" class="content-editor" @submit.prevent="saveAnnouncement"><div class="editor-heading"><h2>{{ announcementDraft.id?'编辑公告':'新增公告' }}</h2><button class="icon-close" type="button" aria-label="关闭" @click="announcementDraft=null">×</button></div><div class="content-fields"><label>标题<input v-model.trim="announcementDraft.title" maxlength="150" required></label><label>摘要<input v-model.trim="announcementDraft.summary" maxlength="500"></label><label>正文<textarea v-model.trim="announcementDraft.body" maxlength="10000" rows="7" required></textarea></label><label>排序<input v-model.number="announcementDraft.sortOrder" type="number" min="0"></label><label>开始时间<input v-model="announcementDraft.startAt" type="datetime-local" required></label><label>结束时间<input v-model="announcementDraft.endAt" type="datetime-local"></label><label class="inline-option"><input v-model="announcementDraft.pinned" type="checkbox">置顶</label><label class="inline-option"><input v-model="announcementDraft.enabled" type="checkbox">启用</label></div><p v-if="saveError" class="form-error">{{ saveError }}</p><button class="primary-button" :disabled="saving">{{ saving?'保存中…':'保存公告' }}</button></form>
    </template>
  </section>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import axios from 'axios'
import http,{type ApiResponse} from '../api/http'
import { imageUrl } from '../api/catalog'
interface Carousel{ id:number;imageId:number;storageKey:string;title:string|null;targetUrl:string|null;sortOrder:number;enabled:boolean;startAt:string;endAt:string|null }
interface Announcement{ id:number;title:string;summary:string|null;body:string;sortOrder:number;pinned:boolean;enabled:boolean;startAt:string;endAt:string|null }
type CarouselDraft={id?:number;imageId:number|null;storageKey:string;title:string;targetUrl:string;sortOrder:number;enabled:boolean;startAt:string;endAt:string}
type AnnouncementDraft={id?:number;title:string;summary:string;body:string;sortOrder:number;pinned:boolean;enabled:boolean;startAt:string;endAt:string}
const tab=ref<'carousel'|'announcement'>('carousel'),carousels=ref<Carousel[]>([]),announcements=ref<Announcement[]>([]),loading=ref(false),saving=ref(false),error=ref(''),saveError=ref(''),carouselDraft=ref<CarouselDraft|null>(null),announcementDraft=ref<AnnouncementDraft|null>(null)
async function load(){loading.value=true;error.value='';try{const [c,a]=await Promise.all([http.get<ApiResponse<Carousel[]>>('/api/v1/admin/content/carousels'),http.get<ApiResponse<Announcement[]>>('/api/v1/admin/content/announcements')]);carousels.value=c.data.data;announcements.value=a.data.data}catch{error.value='内容列表加载失败。'}finally{loading.value=false}}
function switchTab(value:'carousel'|'announcement'){tab.value=value;carouselDraft.value=null;announcementDraft.value=null;saveError.value=''}
function dateNow(){const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,16)}
function carouselImage(key:string){return imageUrl(`/api/v1/public/product-images/${key}`)}
function newCarousel(){carouselDraft.value={imageId:null,storageKey:'',title:'',targetUrl:'',sortOrder:0,enabled:false,startAt:dateNow(),endAt:''};saveError.value=''}
function editCarousel(item:Carousel){carouselDraft.value={id:item.id,imageId:item.imageId,storageKey:item.storageKey,title:item.title??'',targetUrl:item.targetUrl??'',sortOrder:item.sortOrder,enabled:item.enabled,startAt:item.startAt.slice(0,16),endAt:item.endAt?.slice(0,16)??''};saveError.value=''}
async function uploadImage(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!carouselDraft.value)return;const data=new FormData();data.append('file',file);try{const image=(await http.post<ApiResponse<{id:number;url:string}>>('/api/v1/admin/product-images',data)).data.data;carouselDraft.value.imageId=image.id;carouselDraft.value.storageKey=image.url.split('/').pop()??''}catch{saveError.value='图片上传失败，请使用有效的 PNG、JPEG 或 WebP 图片。'}}
async function saveCarousel(){const d=carouselDraft.value;if(!d?.imageId){saveError.value='请先上传轮播图图片。';return}await submit(async()=>{const payload={imageId:d.imageId,title:d.title||null,targetUrl:d.targetUrl||null,sortOrder:d.sortOrder,enabled:d.enabled,startAt:d.startAt,endAt:d.endAt||null};if(d.id)await http.put(`/api/v1/admin/content/carousels/${d.id}`,payload);else await http.post('/api/v1/admin/content/carousels',payload);carouselDraft.value=null})}
function newAnnouncement(){announcementDraft.value={title:'',summary:'',body:'',sortOrder:0,pinned:false,enabled:false,startAt:dateNow(),endAt:''};saveError.value=''}
function editAnnouncement(item:Announcement){announcementDraft.value={id:item.id,title:item.title,summary:item.summary??'',body:item.body,sortOrder:item.sortOrder,pinned:item.pinned,enabled:item.enabled,startAt:item.startAt.slice(0,16),endAt:item.endAt?.slice(0,16)??''};saveError.value=''}
async function saveAnnouncement(){const d=announcementDraft.value;if(!d)return;await submit(async()=>{const payload={...d,summary:d.summary||null,endAt:d.endAt||null};if(d.id)await http.put(`/api/v1/admin/content/announcements/${d.id}`,payload);else await http.post('/api/v1/admin/content/announcements',payload);announcementDraft.value=null})}
async function submit(action:()=>Promise<unknown>){saving.value=true;saveError.value='';try{await action();await load()}catch(error){const responseMessage=axios.isAxiosError<{message?:unknown}>(error)?error.response?.data?.message:null;saveError.value=typeof responseMessage==='string'&&responseMessage.trim()?responseMessage:'保存失败，请检查网络连接、必填内容和账户权限。'}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>
.content-page{max-width:1100px}.content-tabs{display:flex;gap:18px;border-bottom:1px solid #dce4de}.content-tabs button{padding:12px 2px;border:0;border-bottom:2px solid transparent;background:none;color:#65736b}.content-tabs button[aria-pressed=true]{border-bottom-color:#278258;color:#237149;font-weight:600}.content-toolbar{display:flex;justify-content:space-between;align-items:center;padding:16px 0;color:#66736b;font-size:13px}.content-list{border-top:1px solid #e6ebe7}.content-row,.announcement-row{display:flex;align-items:center;gap:16px;padding:14px 0;border-bottom:1px solid #e6ebe7}.content-row>img{width:128px;height:72px;object-fit:cover;background:#f0f3f1}.content-row-main{display:grid;gap:5px;flex:1;min-width:0}.content-row-main strong{overflow-wrap:anywhere}.content-row small,.announcement-row small{color:#77847c;font-size:12px;overflow-wrap:anywhere}.announcement-row>div{flex:1;min-width:0}.announcement-row p{margin:6px 0;max-height:3em;overflow:hidden;color:#536159;font-size:13px;overflow-wrap:anywhere}.content-editor{margin-top:24px;padding:20px 0;border-top:1px solid #cbd5ce}.editor-heading{display:flex;justify-content:space-between;align-items:center}.editor-heading h2{font-size:17px}.icon-close{border:0;background:none;font-size:24px;color:#56645c}.content-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.content-fields label{display:grid;gap:6px;color:#536159;font-size:13px}.content-fields input:not([type=checkbox]),.content-fields textarea{width:100%;min-width:0;min-height:38px;padding:8px 10px;border:1px solid #cbd5ce;border-radius:4px;font:inherit}.content-fields textarea{resize:vertical}.content-fields label:nth-child(3){grid-column:1/-1}.content-fields .inline-option{display:flex;align-items:center;gap:8px}.inline-option input{accent-color:#278258}.image-preview{display:block;width:min(320px,100%);max-height:160px;object-fit:contain;object-position:left top}.empty-state,.page-status{padding:20px 0;color:#69766e}.form-error{padding:12px 0;color:#b54841}@media(max-width:600px){.content-fields{grid-template-columns:1fr}.content-fields label:nth-child(3){grid-column:auto}.content-row{align-items:flex-start}.content-row>img{width:90px;height:56px}}
</style>
